/**
 * Shared helpers for the line-oriented subtitle parsers.
 */

/** Strip a UTF-8 byte-order mark if present. */
function stripBom(text) {
  return text.charCodeAt(0) === 0xfeff ? text.slice(1) : text;
}

/**
 * Split source text into lines, normalising CRLF and lone CR.
 * @param {string} text
 * @returns {string[]}
 */
function toLines(text) {
  return stripBom(text).replace(/\r\n?/g, '\n').split('\n');
}

/**
 * Group lines into blocks separated by blank lines, remembering where each
 * block started so diagnostics can point at a real line number.
 *
 * @param {string[]} lines
 * @returns {{lines: string[], line: number}[]}
 */
function groupBlocks(lines) {
  const blocks = [];
  let current = null;
  for (let i = 0; i < lines.length; i += 1) {
    const line = lines[i];
    if (line.trim() === '') {
      if (current) {
        blocks.push(current);
        current = null;
      }
      continue;
    }
    if (!current) current = { lines: [], line: i + 1 };
    current.lines.push(line);
  }
  if (current) blocks.push(current);
  return blocks;
}

