/**
 * Timecode and frame-rate arithmetic.
 *
 * Frame rates are stored as exact rationals. 23.976 is really 24000/1001 and
 * treating it as 23.976 accumulates error that shows up as off-by-one frame
 * gaps on long files, which is precisely the class of bug this tool exists to
 * catch.
 */

/** Canonical frame rates, as exact rationals. */
const FRAME_RATES = {
  '23.976': 24000 / 1001,
  '23.98': 24000 / 1001,
  '24': 24,
  '25': 25,
  '29.97': 30000 / 1001,
  '30': 30,
  '48': 48,
  '50': 50,
  '59.94': 60000 / 1001,
  '60': 60,
};

/**
 * Resolve a user-supplied frame rate to a number.
 * Accepts a canonical key ('23.976'), a bare number, or a numeric string.
 * @param {string|number} value
 * @returns {number} frames per second
 */
function resolveFrameRate(value) {
  if (value === undefined || value === null || value === '') return FRAME_RATES['25'];
  if (typeof value === 'number') {
    if (!Number.isFinite(value) || value <= 0) {
      throw new RangeError(`Invalid frame rate: ${value}`);
    }
    // Snap common decimal approximations onto their exact rational form.
    if (Math.abs(value - 23.976) < 0.002) return FRAME_RATES['23.976'];
    if (Math.abs(value - 29.97) < 0.002) return FRAME_RATES['29.97'];
    if (Math.abs(value - 59.94) < 0.002) return FRAME_RATES['59.94'];
    return value;
  }
  const key = String(value).trim();
  if (Object.prototype.hasOwnProperty.call(FRAME_RATES, key)) return FRAME_RATES[key];
  const num = Number(key);
  if (!Number.isFinite(num) || num <= 0) {
    throw new RangeError(
      `Unknown frame rate "${value}". Known: ${Object.keys(FRAME_RATES).join(', ')}`,
    );
  }
  return resolveFrameRate(num);
}

/**
 * Convert a frame count to milliseconds at a given rate.
 * @param {number} frames
 * @param {number} fps
 * @returns {number} milliseconds (not rounded)
 */
function framesToMs(frames, fps) {
  return (frames * 1000) / fps;
}

/**
 * Convert milliseconds to a frame count at a given rate.
 * @param {number} ms
 * @param {number} fps
 * @returns {number} frames (not rounded)
 */
function msToFrames(ms, fps) {
  return (ms * fps) / 1000;
}

const TS_FULL = /^(?:(\d+):)?(\d{1,3}):(\d{1,2})(?:[.,](\d{1,3}))?$/;

/**
 * Parse a subtitle timestamp into milliseconds.
 *
 * Handles the shapes that actually occur in the wild:
 *   00:00:01,000   SRT
 *   00:00:01.000   WebVTT
 *   00:01.000      WebVTT short form (mm:ss.mmm)
 *   0:00:01.00     ASS (centiseconds)
 *
 * @param {string} raw
 * @returns {number} milliseconds
 * @throws {SyntaxError} when the timestamp cannot be understood
 */
function parseTimestamp(raw) {
  if (typeof raw !== 'string') throw new SyntaxError(`Timestamp is not a string: ${raw}`);
  const s = raw.trim();
  const m = TS_FULL.exec(s);
  if (!m) throw new SyntaxError(`Unrecognised timestamp: "${raw}"`);

  let [, hh, mm, ss, frac] = m;

  // Short form mm:ss.mmm — the regex puts mm in group 2 and ss in group 3.
  const hours = hh === undefined ? 0 : Number(hh);
  const minutes = Number(mm);
  const seconds = Number(ss);

  if (minutes > 59 && hh !== undefined) {
    throw new SyntaxError(`Minutes out of range in "${raw}"`);
  }
  if (seconds > 59) {
    throw new SyntaxError(`Seconds out of range in "${raw}"`);
  }

  let millis = 0;
  if (frac !== undefined) {
    // 2 digits means centiseconds (ASS), 3 means milliseconds, 1 means deciseconds.
    if (frac.length === 1) millis = Number(frac) * 100;
    else if (frac.length === 2) millis = Number(frac) * 10;
    else millis = Number(frac);
  }

  return hours * 3600000 + minutes * 60000 + seconds * 1000 + millis;
}

/**
 * Format milliseconds as hh:mm:ss,mmm (SRT style) for human-readable reports.
 * Negative values are clamped to zero and marked.
 * @param {number} ms
 * @returns {string}
 */
function formatTimestamp(ms) {
  const negative = ms < 0;
  const total = Math.abs(Math.round(ms));
  const hours = Math.floor(total / 3600000);
  const minutes = Math.floor((total % 3600000) / 60000);
  const seconds = Math.floor((total % 60000) / 1000);
  const millis = total % 1000;
  const body =
    `${String(hours).padStart(2, '0')}:${String(minutes).padStart(2, '0')}:` +
    `${String(seconds).padStart(2, '0')},${String(millis).padStart(3, '0')}`;
  return negative ? `-${body}` : body;
}

/**
 * Format milliseconds as a timecode with frames, hh:mm:ss:ff.
 * @param {number} ms
 * @param {number} fps
 * @returns {string}
 */
function formatFrames(ms, fps) {
  const total = Math.max(0, ms);
  const hours = Math.floor(total / 3600000);
  const minutes = Math.floor((total % 3600000) / 60000);
  const seconds = Math.floor((total % 60000) / 1000);
  const frames = Math.floor(msToFrames(total % 1000, fps));
  return [hours, minutes, seconds, frames]
    .map((n) => String(n).padStart(2, '0'))
    .join(':');
}

