/**
 * SubRip (.srt) parser.
 *
 * SRT has no specification, only a very large body of practice. This parser is
 * deliberately forgiving about everything except the timing line, because a
 * QC tool that refuses to open a slightly malformed file is useless — the
 * malformed files are exactly the ones you need to inspect.
 */



const SRT_ARROW = /-{2,}>|\u2192/;
// Optional trailing display coordinates, e.g. "X1:100 X2:500 Y1:200 Y2:250".
const COORDS = /\s+X1:\s*-?\d+.*$/i;

/**
 * @param {string} source
 * @returns {{format: string, cues: object[], errors: {line: number, message: string}[]}}
 */
function parseSrt(source) {
  const lines = toLines(source);
  const blocks = groupBlocks(lines);
  const cues = [];
  const errors = [];

  for (const block of blocks) {
    const arrowAt = block.lines.findIndex((l) => SRT_ARROW.test(l));

    if (arrowAt === -1) {
      // No timing line. If we already have a cue this is almost certainly a
      // paragraph break inside its text, so fold it back in rather than lose it.
      if (cues.length > 0) {
        const prev = cues[cues.length - 1];
        prev.text += `\n${block.lines.join('\n')}`;
      } else {
        errors.push({
          line: block.line,
          message: 'Block has no "-->" timing line and no preceding cue to attach to',
        });
      }
      continue;
    }

    const header = block.lines.slice(0, arrowAt).filter((l) => l.trim() !== '');
    const id = header.length ? header[header.length - 1].trim() : null;
    const timingLine = block.lines[arrowAt];
    const timingLineNumber = block.line + arrowAt;

    const cleaned = timingLine.replace(COORDS, '');
    const parts = cleaned.split(SRT_ARROW);
    if (parts.length < 2) {
      errors.push({ line: timingLineNumber, message: `Malformed timing line: "${timingLine}"` });
      continue;
    }

    let start;
    let end;
    try {
      start = parseTimestamp(parts[0]);
      end = parseTimestamp(parts[1]);
    } catch (err) {
      errors.push({ line: timingLineNumber, message: err.message });
      continue;
    }

    const text = block.lines.slice(arrowAt + 1).join('\n');

    cues.push({
      index: cues.length + 1,
      id,
      start,
      end,
      text,
      format: 'srt',
      line: block.line,
      settings: null,
      style: null,
    });
  }

  return { format: 'srt', cues, errors };
}

// ---- src/parse/vtt.js ----
/**
 * WebVTT parser.
 *
 * Follows the block structure described in the W3C WebVTT specification:
 * a WEBVTT header, then any number of NOTE, STYLE, REGION and cue blocks.
 * Cue settings after the timing arrow are preserved, because losing them is a
 * real bug in other tools and a rule may want to inspect them later.
 */



const VTT_ARROW = /-{2,}>/;

/**
 * Parse the space-separated `key:value` settings that may follow the arrow.
 * @param {string} raw
 * @returns {Record<string,string>|null}
 */
function parseSettings(raw) {
  const trimmed = (raw || '').trim();
  if (!trimmed) return null;
  const settings = {};
  for (const token of trimmed.split(/\s+/)) {
    const colon = token.indexOf(':');
    if (colon > 0) settings[token.slice(0, colon)] = token.slice(colon + 1);
  }
  return Object.keys(settings).length ? settings : null;
}

/**
 * @param {string} source
 * @returns {{format: string, cues: object[], errors: {line: number, message: string}[]}}
 */
function parseVtt(source) {
  const lines = toLines(source);
  const blocks = groupBlocks(lines);
  const cues = [];
  const errors = [];

  if (blocks.length === 0 || !/^WEBVTT(\s|$)/.test(blocks[0].lines[0] || '')) {
    errors.push({
      line: 1,
      message: 'File does not start with the required "WEBVTT" header',
    });
  }

  for (let b = 0; b < blocks.length; b += 1) {
    const block = blocks[b];
    const first = block.lines[0];

    if (b === 0 && /^WEBVTT(\s|$)/.test(first)) continue;
    if (/^NOTE(\s|$)/.test(first)) continue;
    if (/^STYLE(\s|$)/.test(first)) continue;
    if (/^REGION(\s|$)/.test(first)) continue;

    const arrowAt = block.lines.findIndex((l) => VTT_ARROW.test(l));
    if (arrowAt === -1) {
      if (cues.length > 0) {
        cues[cues.length - 1].text += `\n${block.lines.join('\n')}`;
      } else {
        errors.push({
          line: block.line,
          message: 'Block has no "-->" timing line and no preceding cue to attach to',
        });
      }
      continue;
    }

    const header = block.lines.slice(0, arrowAt).filter((l) => l.trim() !== '');
    const id = header.length ? header[header.length - 1].trim() : null;
    const timingLine = block.lines[arrowAt];
    const timingLineNumber = block.line + arrowAt;

    const arrowMatch = VTT_ARROW.exec(timingLine);
    const before = timingLine.slice(0, arrowMatch.index);
    const after = timingLine.slice(arrowMatch.index + arrowMatch[0].length);

    // Everything up to the first whitespace after the arrow is the end time;
    // the remainder is cue settings.
    const afterTrimmed = after.replace(/^\s+/, '');
    const spaceAt = afterTrimmed.search(/\s/);
    const endRaw = spaceAt === -1 ? afterTrimmed : afterTrimmed.slice(0, spaceAt);
    const settingsRaw = spaceAt === -1 ? '' : afterTrimmed.slice(spaceAt);

    let start;
    let end;
    try {
      start = parseTimestamp(before);
      end = parseTimestamp(endRaw);
    } catch (err) {
      errors.push({ line: timingLineNumber, message: err.message });
      continue;
    }

    cues.push({
      index: cues.length + 1,
      id,
      start,
      end,
      text: block.lines.slice(arrowAt + 1).join('\n'),
      format: 'vtt',
      line: block.line,
      settings: parseSettings(settingsRaw),
      style: null,
    });
  }

  return { format: 'vtt', cues, errors };
}

// ---- src/parse/ass.js ----
/**
 * Advanced SubStation Alpha (.ass / .ssa) parser.
 *
 * The Events section declares its own field order on a `Format:` line, and the
 * Text field is always last and may itself contain commas. Splitting on every
 * comma is the classic bug here, so we split only as many times as there are
 * declared fields before Text.
 */



const DEFAULT_EVENT_FORMAT = [
  'Layer',
  'Start',
  'End',
  'Style',
  'Name',
  'MarginL',
  'MarginR',
  'MarginV',
  'Effect',
  'Text',
];

/**
 * @param {string} source
 * @returns {{format: string, cues: object[], errors: {line: number, message: string}[]}}
 */
function parseAss(source) {
  const lines = toLines(source);
  const cues = [];
  const errors = [];
  const styles = new Set();

  let section = null;
  let eventFormat = null;
  let sawEvents = false;

  for (let i = 0; i < lines.length; i += 1) {
    const raw = lines[i];
    const line = raw.trim();
    const lineNumber = i + 1;

    if (line === '' || line.startsWith(';') || line.startsWith('!:')) continue;

    const sectionMatch = /^\[(.+)\]$/.exec(line);
    if (sectionMatch) {
      section = sectionMatch[1].toLowerCase();
      if (section === 'events') sawEvents = true;
      continue;
    }

    const colon = line.indexOf(':');
    if (colon === -1) continue;
    const key = line.slice(0, colon).trim().toLowerCase();
    const value = line.slice(colon + 1);

    if (section && section.includes('styles') && key === 'style') {
      const name = value.split(',')[0];
      if (name) styles.add(name.trim());
      continue;
    }

    if (section !== 'events') continue;

    if (key === 'format') {
      eventFormat = value.split(',').map((f) => f.trim());
      continue;
    }

    if (key === 'comment') continue;
    if (key !== 'dialogue') continue;

    const fields = eventFormat || DEFAULT_EVENT_FORMAT;
    const textAt = fields.findIndex((f) => f.toLowerCase() === 'text');
    const splitCount = textAt === -1 ? fields.length - 1 : textAt;

    // Split into exactly splitCount parts plus the remainder.
    const parts = [];
    let rest = value;
    for (let s = 0; s < splitCount; s += 1) {
      const comma = rest.indexOf(',');
      if (comma === -1) {
        parts.push(rest);
        rest = '';
        break;
      }
      parts.push(rest.slice(0, comma));
      rest = rest.slice(comma + 1);
    }
    parts.push(rest);

    const record = {};
    for (let f = 0; f < fields.length && f < parts.length; f += 1) {
      record[fields[f].toLowerCase()] = parts[f];
    }

    if (record.start === undefined || record.end === undefined) {
      errors.push({ line: lineNumber, message: 'Dialogue line is missing Start or End' });
      continue;
    }

    let start;
    let end;
    try {
      start = parseTimestamp(record.start);
      end = parseTimestamp(record.end);
    } catch (err) {
      errors.push({ line: lineNumber, message: err.message });
      continue;
    }

    const text = (record.text || '').trim();

    cues.push({
      index: cues.length + 1,
      id: record.name ? record.name.trim() || null : null,
      start,
      end,
      text,
      format: 'ass',
      line: lineNumber,
      settings: null,
      style: record.style ? record.style.trim() : null,
      layer: record.layer !== undefined ? Number(record.layer) || 0 : 0,
    });
  }

  if (!sawEvents) {
    errors.push({ line: 1, message: 'No [Events] section found' });
  }

  return { format: 'ass', cues, errors, styles: [...styles] };
}

// ---- src/parse/index.js ----
/**
 * Format detection and parser dispatch.
 */






/**
 * Guess a subtitle format from its content, falling back to the file extension.
 *
 * Content wins over extension because mislabelled files are common — a .srt
 * that is really a WebVTT is a routine delivery mistake, and one worth telling
 * the user about rather than silently mis-parsing.
 *
 * @param {string} source
 * @param {string} [filename]
 * @returns {'srt'|'vtt'|'ass'|null}
 */
function detectFormat(source, filename = '') {
  const head = stripBom(source || '').slice(0, 4096);

  // Anchored to the very start of the file, not to any line. A multiline anchor
  // would misdetect an SRT whose subtitle text happens to begin a line with the
  // word WEBVTT.
  if (/^WEBVTT(\s|$)/.test(head.trimStart())) return 'vtt';
  if (/^\s*\[Script Info\]/im.test(head) || /^\s*\[V4\+? Styles\]/im.test(head)) return 'ass';
  if (/^\s*\[Events\]/im.test(head)) return 'ass';
  if (/\d{1,3}:\d{2}:\d{2}[.,]\d{1,3}\s*-{2,}>/.test(head)) return 'srt';
  if (/\d{1,2}:\d{2}:\d{2}\.\d{2},/.test(head) && /Dialogue:/i.test(head)) return 'ass';

  const ext = String(filename).toLowerCase().match(/\.([a-z0-9]+)$/);
  if (ext) {
    if (ext[1] === 'vtt') return 'vtt';
    if (ext[1] === 'ass' || ext[1] === 'ssa') return 'ass';
    if (ext[1] === 'srt') return 'srt';
  }
  return null;
}

/**
 * Parse subtitle source text.
 *
 * @param {string} source
 * @param {object} [options]
 * @param {string} [options.filename] used as a hint and echoed into the result
 * @param {'srt'|'vtt'|'ass'} [options.format] force a format
 * @returns {{format: string, cues: object[], errors: object[], filename: string}}
 */
function parse(source, options = {}) {
  if (typeof source !== 'string') {
    throw new TypeError('parse() expects the subtitle source as a string');
  }
  const filename = options.filename || '';
  const format = options.format || detectFormat(source, filename);

  if (!format) {
    return {
      format: null,
      cues: [],
      filename,
      errors: [
        {
          line: 1,
          message:
            'Could not determine subtitle format. Supported: .srt, .vtt, .ass/.ssa. ' +
            'Pass --format to override.',
        },
      ],
    };
  }

  let result;
  if (format === 'srt') result = parseSrt(source);
  else if (format === 'vtt') result = parseVtt(source);
  else if (format === 'ass') result = parseAss(source);
  else throw new RangeError(`Unsupported format "${format}"`);

  // Detection mismatch is itself worth reporting.
  const detected = detectFormat(source, filename);
  if (options.format && detected && detected !== options.format) {
    result.errors = [
      {
        line: 1,
        message: `Parsed as ${options.format} but the content looks like ${detected}`,
      },
      ...result.errors,
    ];
  }

  return { ...result, filename };
}

