/**
 * Netflix Timed Text Style Guide.
 *
 * Every threshold below carries the URL it came from and a quoted clause.
 * That is deliberate: the single most common failure mode in subtitle QC is
 * two people confidently citing different numbers for the same platform. A
 * working QC professional publicly cites Netflix at 17 CPS; the English style
 * guide says 20. Both are "right" — 17 is the template figure and the default
 * for most non-English languages, 20 is English original-language subtitling.
 * Printing the citation next to the number is how that argument ends.
 */

const TTSG_GENERAL =
  'https://partnerhelp.netflixstudios.com/hc/en-us/articles/215758617-Timed-Text-Style-Guide-General-Requirements';
const TTSG_EN =
  'https://partnerhelp.netflixstudios.com/hc/en-us/articles/217350977-English-USA-Timed-Text-Style-Guide';
const TTSG_TIMING =
  'https://partnerhelp.netflixstudios.com/hc/en-us/articles/360051554394-Timed-Text-Style-Guide-Subtitle-Timing-Guidelines';
const SE_ENCODING =
  'https://github.com/SubtitleEdit/subtitleedit/blob/main/src/ui/Logic/NetflixQualityCheck/NetflixQualityController.cs';

/**
 * Per-language reading speeds, in characters per second.
 * Primary sources are Netflix's per-language style guides. The consolidated
 * table below is transcribed from Subtitle Edit's encoding of those guides,
 * which is a secondary source — flagged honestly in the citation.
 */
const CPS_BY_VARIANT = {
  adult: { default: 17, en: 20, ar: 20, hi: 22, ja: 4, ko: 12, zh: 9 },
  children: { default: 13, en: 17, ar: 17, hi: 18, ja: 4, ko: 9, zh: 7 },
  sdh: { default: 20, en: 20, ar: 23, hi: 25, ja: 7, ko: 14, zh: 11 },
  'children-sdh': { default: 17, en: 17, ar: 20, hi: 20, ja: 7, ko: 11, zh: 9 },
};

const LINE_LENGTH_BY_LANG = { default: 42, ja: 23, th: 35, ko: 16, zh: 16, ru: 39 };

function cpsRule(variant, lang) {
  const table = CPS_BY_VARIANT[variant] || CPS_BY_VARIANT.adult;
  const max = Object.prototype.hasOwnProperty.call(table, lang) ? table[lang] : table.default;
  const isPrimary = lang === 'en' && (variant === 'adult' || variant === 'children');
  return {
    max,
    unit: 'cps',
    severity: 'error',
    source: {
      url: isPrimary ? TTSG_EN : SE_ENCODING,
      quote: isPrimary
        ? 'Adult programs: 20 characters per second. Children’s programs: 17 characters per second.'
        : `Per-language value for "${lang}" (${variant}). Transcribed from Subtitle Edit’s ` +
          'encoding of the Netflix per-language style guides; secondary source, not verified ' +
          'against each individual language page.',
      confidence: isPrimary ? 'primary' : 'secondary',
    },
  };
}

